def median(xs):
    xs_sorted = sorted(xs)
    n = len(xs_sorted)
    if n % 2 == 1:
        return xs_sorted[n // 2]
    else:
        return (xs_sorted[n // 2 - 1] + xs_sorted[n // 2]) / 2
